export const codigoRenderizadorIndicadores = "function criarRenderizadorIndicadores(catalogo) {\n    const cache = new Map();\n    // Pictogramas vetoriais locais; nao dependem do CDN de icones do mapa.\n    const pictogramas = {\n        onibus: '<rect x=\"5\" y=\"3\" width=\"14\" height=\"16\" rx=\"3\"/><path d=\"M5 11h14M8 3v8M16 3v8M7 19v2M17 19v2\"/><path d=\"M8 15h.01M16 15h.01\" stroke-width=\"3\"/>',\n        brt: '<rect x=\"2\" y=\"5\" width=\"20\" height=\"13\" rx=\"2\"/><path d=\"M5 8h3v4H5zM16 8h3v4h-3zM11 6v11M13 6v11\"/><circle cx=\"6\" cy=\"19\" r=\"1\"/><circle cx=\"18\" cy=\"19\" r=\"1\"/>',\n        trem: '<rect x=\"5\" y=\"3\" width=\"14\" height=\"15\" rx=\"4\"/><path d=\"M5 10h14M9 3h6M8 18l-3 3M16 18l3 3M7 21h10\"/><path d=\"M8 14h.01M16 14h.01\" stroke-width=\"3\"/>',\n    };\n    return function renderizar(estilo, modal, cor) {\n        // Somente hex: cores das linhas sao selecionadas pela paleta do app.\n        const color = /^#[0-9a-f]{6}$/i.test(cor)\n            ? cor\n            : /^#[0-9a-f]{3}$/i.test(cor)\n                ? \"#\" +\n                    cor\n                        .slice(1)\n                        .split(\"\")\n                        .map(function (c) {\n                        return c + c;\n                    })\n                        .join(\"\")\n                : \"#FFC400\";\n        const key = estilo + \":\" + modal + \":\" + color.toLowerCase();\n        const anterior = cache.get(key);\n        if (anterior)\n            return anterior;\n        const a = catalogo[estilo].assets[modal];\n        let svg = a.svg\n            .replace(/<!--[\\s\\S]*?-->/g, \"\")\n            .replace(/(<g\\b[^>]*\\bid=\"carroceria\"[^>]*\\bfill=\")[^\"]*(\")/, \"$1\" + color + \"$2\");\n        // Os assets realistas usam acentos amarelos fixos em paineis/contornos.\n        // Converte apenas esses acentos para tons da carroceria; vidros e lanternas ficam intactos.\n        const rgb = [1, 3, 5].map(function (i) {\n            return parseInt(color.slice(i, i + 2), 16);\n        });\n        svg = svg.replace(/#(?:604100|885000|ac7000|805200|a76d00|855600|6f4b00|926000)\\b/gi, function (tom) {\n            const fator = Math.max(parseInt(tom.slice(1, 3), 16), parseInt(tom.slice(3, 5), 16), parseInt(tom.slice(5, 7), 16)) / 255;\n            return (\"#\" +\n                rgb\n                    .map(function (c) {\n                    return Math.round(c * fator)\n                        .toString(16)\n                        .padStart(2, \"0\");\n                })\n                    .join(\"\"));\n        });\n        if (a.pictograma) {\n            const canais = rgb.map(function (c) {\n                const s = c / 255;\n                return s <= 0.04045 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4);\n            });\n            const luminancia = 0.2126 * canais[0] + 0.7152 * canais[1] + 0.0722 * canais[2];\n            const contraste = luminancia > 0.179 ? \"#111827\" : \"#FFFFFF\";\n            svg = svg.replace(/<\\/svg>\\s*$/, '<g transform=\"translate(18 16) scale(1.1666667)\" fill=\"none\" stroke=\"' +\n                contraste +\n                '\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">' +\n                pictogramas[modal] +\n                \"</g></svg>\");\n        }\n        const resultado = {\n            svg,\n            uri: \"data:image/svg+xml;charset=utf-8,\" + encodeURIComponent(svg),\n            largura: a.largura,\n            altura: a.altura,\n            ancoraY: a.ancoraY,\n            orientacao: a.orientacao,\n        };\n        if (cache.size >= 256)\n            cache.delete(cache.keys().next().value);\n        cache.set(key, resultado);\n        return resultado;\n    };\n}\n";
